 143	import java.math.BigDecimal;
 144	import java.math.RoundingMode;
 145	import java.time.LocalDate;
 146	import java.time.Month;
 147	
 148	/**
 149	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 150	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 151	 * (half-even) at every step.
 152	 */
 153	public final class PriceCalculator {
 154	
 155	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 156	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 157	
 158	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 159	        int nights = 0;
 160	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 161	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 162	            subtotal = subtotal.add(nightPrice(room, night));
 163	            nights++;
 164	        }
 165	        BigDecimal discount = switch (ratePlan) {
 166	            case STANDARD -> cents(BigDecimal.ZERO);
 167	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 168	        };
 169	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 170	    }
 171	
 172	    BigDecimal nightPrice(Room room, LocalDate night) {
 173	        BigDecimal nightlyRate = room.nightlyRate();
 174	        if (isHighSeason(night)) {
 175	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 176	        }
 177	        return cents(nightlyRate);
 178	    }
 179	
 180	    /** High season: from December 15 to the end of February, and the whole of July. */
 181	    static boolean isHighSeason(LocalDate date) {
 182	        Month month = date.getMonth();
 183	        return month == Month.JANUARY
 184	                || month == Month.FEBRUARY
 185	                || month == Month.JULY
 186	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
 187	    }
 188	
 189	    static BigDecimal cents(BigDecimal value) {
 190	        return value.setScale(2, RoundingMode.HALF_EVEN);
 191	    }
 192	}
