182	/** Which rooms are occupied on a given night, for the front desk (CSV). */
183	public final class OccupancyReport {
184	
185	    private final Rooms rooms;
186	    private final ReservationStore store;
187	
188	    public OccupancyReport(Rooms rooms, ReservationStore store) {
189	        this.rooms = rooms;
190	        this.store = store;
191	    }
192	
193	    public String generate(LocalDate night) {
194	        List<Reservation> occupying = new ArrayList<>();
195	        for (Reservation reservation : store.all()) {
196	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
197	            if (reservation.isPaid() && coversNight) {
198	                occupying.add(reservation);
199	            }
200	        }
201	        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));
202	
203	        StringBuilder csv = new StringBuilder();
204	        csv.append("room,type,reservation,check_in,check_out\n");
205	        for (Reservation reservation : occupying) {
206	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
207	            csv.append(room.number()).append(',')
208	                    .append(room.type()).append(',')
209	                    .append(reservation.id()).append(',')
210	                    .append(reservation.checkIn()).append(',')
211	                    .append(reservation.checkOut()).append('\n');
212	        }
213	        csv.append("total,").append(occupying.size()).append('/').append(rooms.all().size()).append('\n');
214	        return csv.toString();
215	    }
216	}
