222	import java.time.YearMonth;
223	import java.util.ArrayList;
224	import java.util.Comparator;
225	import java.util.List;
226	
227	/**
228	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
229	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
230	 */
231	public final class RevenueReport {
232	
233	    private final ReservationStore store;
234	
235	    public RevenueReport(ReservationStore store) {
236	        this.store = store;
237	    }
238	
239	    public String generate(YearMonth month) {
240	        List<Reservation> withRevenue = new ArrayList<>();
241	        for (Reservation reservation : store.all()) {
242	            boolean keptMoney = reservation.amountKept().signum() > 0;
243	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
244	            if (keptMoney && startsInMonth) {
245	                withRevenue.add(reservation);
246	            }
247	        }
248	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
249	
250	        StringBuilder csv = new StringBuilder();
251	        csv.append("reservation,room,check_in,check_out,status,amount\n");
252	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
253	        for (Reservation reservation : withRevenue) {
254	            csv.append(reservation.id()).append(',')
255	                    .append(reservation.roomNumber()).append(',')
256	                    .append(reservation.checkIn()).append(',')
257	                    .append(reservation.checkOut()).append(',')
258	                    .append(reservation.status()).append(',')
259	                    .append(reservation.amountKept().toPlainString()).append('\n');
260	            revenue = revenue.add(reservation.amountKept());
261	        }
262	        csv.append("total,").append(revenue.toPlainString()).append('\n');
263	        return csv.toString();
264	    }
265	}

